const D = { energy: .6, scale: 1, speed: 1, density: .6, lean: .3, hue: 8, x: .5, y: .82, style: 'halpha', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Spicules — the chromospheric limb, seen edge-on ---------------------------------------
// Secchi called it the burning prairie. Look at the sun's edge in H-alpha and the smooth limb
// is gone: the whole rim is grass. Millions of SPICULES — jets of chromospheric plasma a few
// hundred km across — are launched up the magnetic field at ~25 km/s, climb to ~7000 km in
// about five minutes, hang, and fall back down the same field line they came up. Nothing here
// ever finishes: every jet runs its own life clock at its own period drawn from the hash, so
// the forest is perpetually a mix of climbing, hanging and draining, and it never re-phases.
// They are not scattered at random either — they crowd the boundaries of supergranular
// network cells, so they come up in BUSHES, and they lean along the field, which is why the
// forest is combed rather than upright. Three depth ranks give parallax and haze: the far rank
// is small, dim and washed into the off-limb glow, the near rank is fat, sharp and dark-rooted.
// In the doppler style the colour is the real observable — a jet climbing toward you is
// blue-shifted, the same jet draining away is red-shifted, so the forest sorts itself into
// approaching and receding without anything else changing.
// ------------------------------------------------------------------------------------------

const TAU = 6.283185307;
const u0 = Math.min(width, height);
const style = P.style;
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const fr2 = (i, j) => { const s = Math.sin(i * 127.1 + j * 311.7 + sd * 74.77) * 43758.5453; return s - Math.floor(s); };

// real-time clock, tolerant of t0 resets
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtr = K.t - S.lastT; S.lastT = K.t;
dtr = dtr < 0 ? 0 : (dtr > 0.06 ? 0.06 : dtr);
if (S.T == null) S.T = 0;
S.T += dtr * (0.25 + P.speed * 0.9);
const ts = S.T;

const en = Math.min(1, Math.max(0, P.energy));
const scl = Math.max(0.4, P.scale);
const dens = Math.min(1, Math.max(0, P.density));
const limbY = Math.min(0.95, Math.max(0.30, P.y)) * height;
const inv = style === 'silhouette' ? 1 : 0;      // on-disk view: bright ground, dark mottles

// incommensurate real-time floor — the whole rim breathes and shears on rates that never re-align
const dr1 = Math.sin(K.t * 0.061) * 0.9 + Math.sin(K.t * 0.143 + 1.7) * 0.5 + Math.sin(K.t * 0.229) * 0.32;
const dr2 = Math.sin(K.t * 0.077 + 2.1) * 0.8 + Math.sin(K.t * 0.181 + 0.4) * 0.44 + Math.sin(K.t * 0.313 + 2.6) * 0.28;

const h2rgb = (h, s, v) => {
  h = (((h % 360) + 360) % 360) / 60;
  const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  if (h < 1) return [c + m, x + m, m];
  if (h < 2) return [x + m, c + m, m];
  if (h < 3) return [m, c + m, x + m];
  if (h < 4) return [m, x + m, c + m];
  if (h < 5) return [x + m, m, c + m];
  return [c + m, m, x + m];
};

// ---- background: chromospheric disk below the limb + off-limb glow above -------------------
const GW = Math.max(260, Math.min(320, Math.round(width / 4.0))), GH = Math.max(48, Math.round(GW * height / width));
if (!S.g || S.key !== width + 'x' + height) { S.g = createGraphics(GW, GH); S.g.pixelDensity(1); S.key = width + 'x' + height; }
const g = S.g;

let sky0, sky1, chrom0, chrom1;
if (style === 'ca_k') { sky0 = [0.035, 0.032, 0.065]; sky1 = h2rgb(268, 0.44, 0.72); chrom0 = h2rgb(262, 0.34, 0.34); chrom1 = h2rgb(258, 0.10, 0.98); }
else if (style === 'silhouette') { sky0 = [0.055, 0.05, 0.048]; sky1 = h2rgb(P.hue + 24, 0.24, 0.80); chrom0 = h2rgb(P.hue + 20, 0.30, 0.52); chrom1 = h2rgb(P.hue + 30, 0.06, 0.99); }
else if (style === 'doppler') { sky0 = [0.03, 0.035, 0.05]; sky1 = [0.30, 0.31, 0.34]; chrom0 = [0.22, 0.23, 0.25]; chrom1 = [0.66, 0.66, 0.67]; }
else if (style === 'sumi') { sky0 = [0.80, 0.775, 0.72]; sky1 = [0.60, 0.575, 0.53]; chrom0 = [0.40, 0.385, 0.35]; chrom1 = [0.10, 0.095, 0.09]; }
else { sky0 = [0.028, 0.018, 0.032]; sky1 = h2rgb(P.hue - 4, 0.92, 0.60); chrom0 = h2rgb(P.hue, 0.86, 0.42); chrom1 = h2rgb(P.hue + 14, 0.30, 1.0); }

const scaleH = (0.085 + en * 0.075) * scl;          // off-limb glow scale height, frame units
const actX = Math.min(1, Math.max(0, P.x));
const lyF = limbY / height;
const curv = 0.20 / Math.max(0.5, scl);             // the limb is an arc, not a ruled line
const limbF = fx => lyF + curv * (fx - 0.5) * (fx - 0.5);

// value noise -> fbm, stretched along the limb so the disk shows FIBRILS, not blobs
const vn = (x, y) => {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const ux = xf * xf * (3 - 2 * xf), uy = yf * yf * (3 - 2 * yf);
  const a = fr2(xi, yi), b = fr2(xi + 1, yi), c = fr2(xi, yi + 1), d = fr2(xi + 1, yi + 1);
  return (a * (1 - ux) + b * ux) * (1 - uy) + (c * (1 - ux) + d * ux) * uy;
};
const fbm = (x, y) => vn(x, y) * 0.55 + vn(x * 2.03 + 11.3, y * 2.03 + 5.7) * 0.28 + vn(x * 4.11 + 3.9, y * 4.11 + 17.1) * 0.17;

g.loadPixels();
const gpx = g.pixels;
for (let j = 0; j < GH; j++) {
  const fy = (j + 0.5) / GH;
  for (let i = 0; i < GW; i++) {
    const fx = (i + 0.5) / GW;
    const ly2 = limbF(fx);
    // a plage: one stretch of rim is magnetically active and burns brighter
    const act = Math.exp(-Math.pow((fx - actX - 0.05 * dr1) / 0.26, 2)) * (0.28 + en * 0.42);
    let v;
    if (fy > ly2) {
      // below the limb: the disk, combed into fibrils that stream and reform along the field
      const d = (fy - ly2) / Math.max(0.02, 1 - ly2);
      const mott = fbm(fx * 7.0 + ts * 0.030 + dr2 * 0.10, fy * 21.0 - ts * 0.012);
      const fine = fbm(fx * 23.0 - ts * 0.021, fy * 46.0 + ts * 0.017);
      v = 0.40 + d * 0.20 + (mott - 0.5) * (0.64 + en * 0.48) + (fine - 0.5) * 0.26 + act * 0.45;
    } else {
      // above it: the glow the forest itself makes, falling off with height, and breathing
      const hh = ly2 - fy;
      const br = 1 + 0.10 * Math.sin(K.t * 0.071 + 1.2) + 0.06 * Math.sin(K.t * 0.163);
      const wisp = fbm(fx * 5.5 + ts * 0.045, fy * 9.0 - ts * 0.055) - 0.5;
      v = (0.50 + act) * br * Math.exp(-hh / (scaleH * (1 + wisp * 0.45)))
        + 0.072 + 0.038 * Math.exp(-hh / (scaleH * 4.5)) + wisp * 0.030 * Math.exp(-hh / (scaleH * 3));
    }
    v = v < 0 ? 0 : (v > 1 ? 1 : v);
    // gradient map, so even the sky is a tone rather than a flat fill
    let R, G2, B;
    if (fy > ly2 || v > 0.34) { const u = Math.min(1, Math.max(0, (v - 0.20) / 0.80)); R = chrom0[0] + (chrom1[0] - chrom0[0]) * u; G2 = chrom0[1] + (chrom1[1] - chrom0[1]) * u; B = chrom0[2] + (chrom1[2] - chrom0[2]) * u; }
    else { const u = Math.min(1, v / 0.34); R = sky0[0] + (sky1[0] - sky0[0]) * u; G2 = sky0[1] + (sky1[1] - sky0[1]) * u; B = sky0[2] + (sky1[2] - sky0[2]) * u; }
    const gn = fr2(i * 2.7 + 1.3, j * 5.1 + 7.9) - 0.5;
    R += gn * 0.045; G2 += gn * 0.045; B += gn * 0.045;
    const o = 4 * (j * GW + i);
    gpx[o] = R < 0 ? 0 : (R > 1 ? 255 : R * 255);
    gpx[o + 1] = G2 < 0 ? 0 : (G2 > 1 ? 255 : G2 * 255);
    gpx[o + 2] = B < 0 ? 0 : (B > 1 ? 255 : B * 255);
    gpx[o + 3] = 255;
  }
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- the forest ---------------------------------------------------------------------------
const N = Math.round(110 + dens * 340);
const NB = Math.max(3, Math.round(5 + dens * 12));      // supergranular network cells along the rim
const hMax = (0.40 + en * 0.34) * scl * height;
const wBase = (0.0034 + en * 0.0026) * scl * u0;
const leanA = (P.lean - 0.5) * 1.10;
const aMul = (P.alpha / 100);

push();
if (!inv && style !== 'sumi') blendMode(ADD);
noStroke();
const NSEG = 5;
for (let q = 0; q < N; q++) {
  const q1 = fr(q * 1.7 + 3.1), q2 = fr(q * 5.3 + 11.7), q3 = fr(q * 9.1 + 23.3), q4 = fr(q * 13.9 + 41.1), q5 = fr(q * 2.9 + 57.7);
  const rank = q % 3;                                    // 0 far, 1 mid, 2 near
  const rz = 0.42 + rank * 0.29;

  // bushes: jets crowd the network boundaries rather than scattering evenly
  const bi = Math.floor(q2 * NB);
  const bx0 = ((bi + 0.5) / NB + (fr(bi * 7.3 + 5) - 0.5) * 0.34 + 0.030 * Math.sin(ts * 0.031 + bi)) ;
  const bx = (bx0 + (q3 - 0.5) * (0.30 / NB) * 3.4) * width;

  const life = (7.5 + q4 * 9.0) / (0.55 + en * 0.75);    // s — its own period, always
  const ph = (ts / life + q1 * 6.13 + q3 * 2.71) % 1;
  const rise = Math.sin(ph * Math.PI);                   // up, hang, drain — then a new one
  if (rise < 0.02) continue;
  const vel = Math.cos(ph * Math.PI);                    // + climbing (blue), - draining (red)

  const h = hMax * rz * (0.42 + q4 * 0.80) * rise;
  const ang0 = leanA * (0.55 + q5 * 0.9) + (q1 - 0.5) * 0.52 + 0.10 * Math.sin(ts * 0.043 + q2 * TAU);
  const bend = (q5 - 0.5) * 0.62 + leanA * 0.35;
  const wq = wBase * rz * (0.55 + q3 * 0.9);

  // brightest mid-flight, dim at birth and death; far rank washed into the glow
  const lum = (0.28 + 0.72 * Math.sin(ph * Math.PI)) * (0.40 + rz * 0.85) * (0.5 + en * 0.75);

  let R, G2, B, aa;
  if (style === 'doppler') {
    // the real observable: sign of the line-of-sight velocity
    const s2 = vel * (0.5 + q3 * 0.7);
    const pos = s2 > 0 ? s2 : 0, neg = s2 < 0 ? -s2 : 0;
    R = 0.30 + neg * 0.92; G2 = 0.30 + Math.abs(s2) * 0.14; B = 0.32 + pos * 0.92;
    aa = 42 * lum * aMul;
  } else if (style === 'sumi') {
    R = 0.16; G2 = 0.15; B = 0.14; aa = 48 * lum * aMul;
  } else if (inv) {
    R = 0.10; G2 = 0.055; B = 0.05; aa = 46 * lum * aMul;   // dark mottles absorbing the disk
  } else if (style === 'ca_k') {
    const cc = h2rgb(266 - vel * 10, 0.30 - lum * 0.16, 1.0);
    R = cc[0]; G2 = cc[1]; B = cc[2]; aa = 34 * lum * aMul;
  } else {
    const cc = h2rgb(P.hue + 8 - lum * 5, 0.92 - lum * 0.34, 1.0);
    R = cc[0]; G2 = cc[1]; B = cc[2]; aa = 29 * lum * aMul;
  }
  if (aa < 1.2) continue;
  fill(0, 0, 0, 0);
  drawingContext.fillStyle = 'rgba(' + Math.round(Math.min(255, R * 255)) + ',' + Math.round(Math.min(255, G2 * 255)) + ',' + Math.round(Math.min(255, B * 255)) + ',' + Math.min(1, aa / 100).toFixed(3) + ')';

  // integrate the centreline up the field line, and rib it out to a tapered ribbon
  let cx = bx, cy = limbF(bx / width) * height + wq * 2, lx = [], ly = [], hw = [];
  const step = h / NSEG;
  for (let k = 0; k <= NSEG; k++) {
    const uu = k / NSEG;
    const ang = ang0 + bend * uu;
    lx.push(cx); ly.push(cy); hw.push(wq * (1 - uu * 0.78) * (0.6 + 0.4 * Math.sin(uu * 3.1 + q1 * 6)));
    cx += Math.sin(ang) * step; cy -= Math.cos(ang) * step;
  }
  beginShape();
  for (let k = 0; k <= NSEG; k++) {
    const ang = ang0 + bend * (k / NSEG);
    vertex(lx[k] + Math.cos(ang) * hw[k], ly[k] + Math.sin(ang) * hw[k]);
  }
  for (let k = NSEG; k >= 0; k--) {
    const ang = ang0 + bend * (k / NSEG);
    vertex(lx[k] - Math.cos(ang) * hw[k], ly[k] - Math.sin(ang) * hw[k]);
  }
  endShape(CLOSE);
}
pop();

// audio rides on top: a bass gust leans the whole forest, treble sparkles the tips.
// Baseline alone already carries everything above; this only adds.
if (A.rms > 0.01 || K.pulse > 0.01) {
  push();
  blendMode(ADD);
  noStroke();
  const lift = (A.bass * 0.55 + K.pulse * 0.22) * (0.4 + en);
  const cc = style === 'sumi' || inv ? [0.5, 0.48, 0.45] : h2rgb(P.hue + 10, 0.5, 1);
  fill(0, 0, 0, 0);
  drawingContext.fillStyle = 'rgba(' + Math.round(cc[0] * 255) + ',' + Math.round(cc[1] * 255) + ',' + Math.round(cc[2] * 255) + ',' + Math.min(1, lift * 0.10 * aMul).toFixed(3) + ')';
  rect(0, limbY - hMax * 0.5, width, hMax * 0.5 + (height - limbY));
  pop();
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;
